import json, datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
def w3(n):
    p = []
    h = n // 100
    r = n % 100
    if h:
        p.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        p.append(TENS[r // 10])
    if r % 10:
        p.append(ONES[r % 10])
    return ' '.join(p)
def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    p = []
    for val, nm in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        g = n // val
        if g:
            if val == 1000 and g == 1:
                p.append('bin')
            else:
                p.append(w3(g) + ' ' + nm)
            n = n % val
    if n:
        p.append(w3(n))
    return ' '.join(p)
def num(x):
    try:
        return float(str(x).replace(',', '.'))
    except Exception:
        return 0.0
def split_amt(x):
    c = int(round(abs(num(x)) * 100))
    return c // 100, c % 100
def amount(x, cur, final=False):
    w, k = split_amt(x)
    W = words(w)
    if cur == 'TL':
        if k:
            return W + ' lira ' + words(k) + (' kuruştur' if final else ' kuruş')
        return W + (" Türk Lirası'dır" if final else ' Türk Lirası')
    if cur == 'GBP':
        if k:
            return W + ' İngiliz Sterlini ' + words(k) + (" peni'dir" if final else ' peni')
        return W + (" İngiliz Sterlini'dir" if final else ' İngiliz Sterlini')
    small = 'dolar' if cur == 'USD' else 'euro'
    big = 'dolar' if cur == 'USD' else 'euro'
    if k:
        return W + ' ' + small + ' ' + words(k) + (" sent'tir" if final else ' sent')
    if final:
        return W + ' ' + big + ("'dır" if cur == 'USD' else "'dur")
    return W + ' ' + big
def pdate(s):
    try:
        s = str(s).strip()
        d, m, y = s.split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None
def sdate(s):
    d = pdate(s)
    if not d:
        return str(s)
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)
def date_cop(s):
    d = pdate(s)
    if not d:
        return str(s)
    y = d.year
    last = y % 10
    if last == 0:
        t = (y % 100) // 10
        suf = ["'dır", "'dur", "'dir", "'dur", "'tır", "'dir", "'tır", "'dir", "'dir", "'dır"][t]
    else:
        suf = ['', "'dir", "'dir", "'tür", "'tür", "'tir", "'dır", "'dir", "'dir", "'dur"][last]
    return sdate(s) + suf
def digits(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())
def clean_name(n):
    n = str(n or '').strip()
    if len(n) > 40 or 'talimat' in n.lower() or 'ignore' in n.lower():
        return ''
    return n
def today_of(vars):
    try:
        return datetime.date.fromisoformat(str(vars.get('now') or '')[:10])
    except Exception:
        return datetime.date.today()
def classify(result):
    if not isinstance(result, dict):
        return 'error', '', dict()
    result.pop('header', None)
    try:
        sc = int(result.get('status_code') or 200)
    except Exception:
        sc = 200
    d = result.get('data')
    if isinstance(d, str):
        try:
            d = json.loads(d)
        except Exception:
            d = None
    if not isinstance(d, dict):
        return 'error', '', dict()
    r = d.get('result')
    if not isinstance(r, dict):
        r = dict()
    rc = str(r.get('returnCode', r.get('code', '')))
    inner = d.get('data')
    if sc >= 400 or rc != '1' or not isinstance(inner, dict) or str(result.get('status', 'success')) not in ('success', ''):
        return 'error', rc, inner if isinstance(inner, dict) else dict()
    return 'ok', rc, inner
def set_out(result, what, say=''):
    o = dict()
    o['what_to_do_next'] = what
    if say:
        o['say_text'] = say
    if isinstance(result, dict):
        result['data'] = o

try:
    st, rc, d = classify(result)
    if st != 'ok':
        vars['bal_state'] = 'error'
        set_out(result, 'Teknik hata. Arayana şunu söyle: Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.')
    else:
        today = today_of(vars)
        l4 = str(d.get('cardNumberLast4') or '')
        nm = clean_name(d.get('productName'))
        cards = []
        try:
            cards = json.loads(vars.get('cards_json') or '[]')
        except Exception:
            cards = []
        sel = str(vars.get('sel_card') or '')
        if not sel or sel[-4:] != l4:
            masked = str(d.get('cardNumber') or '')
            cand = [c for c in cards if c['l4'] == l4 and c['n'][:4] == masked[:4]]
            if not cand:
                cand = [c for c in cards if c['l4'] == l4]
            if cand:
                sel = cand[0]['n']
        vars['sel_card'] = sel
        vars['sel_last4'] = l4
        vars['sel_name'] = nm
        sdt = str(d.get('statementDate') or '').strip()
        lpd = str(d.get('lastPayDate') or '').strip()
        vars['statement_date'] = sdt
        cardref = ('Sonu ' + digits(l4) + ' ile biten ' + nm + ' kartınız') if nm else ('Sonu ' + digits(l4) + ' ile biten kartınız')
        multi = False
        try:
            multi = int(str(vars.get('card_count') or '1')) > 1
        except Exception:
            multi = False
        parts = []
        sd = pdate(sdt)
        lp = pdate(lpd)
        if not sdt:
            parts.append(cardref + 'a ait henüz kesilmiş bir ekstre bulunmadığı için ekstre borcunuz bulunmamaktadır.')
        else:
            if sd and sd == today:
                parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
            blocks = [('TL', 'debtTL', 'Türk Lirası'), ('USD', 'debtUSD', 'Dolar'), ('EUR', 'debtEUR', 'Euro'), ('GBP', 'debtGBP', 'İngiliz Sterlini')]
            sentences = []
            nodebt = []
            for cur, key, label in blocks:
                bl = d.get(key)
                if not isinstance(bl, dict):
                    continue
                sdebt = num(bl.get('statementDebt'))
                mn = num(bl.get('minPayment'))
                rem = num(bl.get('remainingDebt'))
                rmn = num(bl.get('remainingMinPayment'))
                if cur == 'TL':
                    if rem <= 0:
                        nodebt.append(label)
                        continue
                    if rmn > 0 and rmn >= mn:
                        s = label + ' borcunuz ' + amount(sdebt, cur) + ', ödenmesi gereken minimum tutar ' + amount(mn, cur, True) + '.'
                    elif rmn <= 0:
                        s = label + ' borcunuz ' + amount(sdebt, cur) + ', kalan toplam borcunuz ' + amount(rem, cur, True) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.'
                    else:
                        s = label + ' borcunuz ' + amount(sdebt, cur) + ', ödenmesi gereken minimum tutar ' + amount(mn, cur) + ', kalan toplam borcunuz ' + amount(rem, cur) + ', kalan minimum ödeme tutarınız ' + amount(rmn, cur, True) + '.'
                    sentences.append(s)
                else:
                    has = rem > 0 or (sdebt > 0 and str(bl.get('statementPaymentStatus')) == 'HAS_DEBT' and rem >= 0 and False)
                    if not has:
                        nodebt.append(label)
                        continue
                    s = label + ' borcunuz ' + amount(sdebt, cur) + ', kalan toplam borcunuz ' + amount(rem, cur) + ', ödenmesi gereken minimum tutar ' + amount(mn, cur, True) + '.'
                    sentences.append(s)
            top_nodebt = str(d.get('statementPaymentStatus')) == 'NO_DEBT'
            if top_nodebt or not sentences:
                tl = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else dict()
                td = num(tl.get('totalDebt'))
                s = cardref + 'ın ' + sdate(sdt) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
                if td > 0:
                    s += ' Gelecek dönemler dahil toplam borcunuz ' + amount(td, 'TL', True) + '.'
                if lpd:
                    s += ' Son ödeme tarihiniz ' + sdate(lpd) + ' olacaktır.'
                parts.append(s)
            else:
                sentences[0] = cardref + 'a ait ' + sdate(sdt) + ' tarihinde kesilen ekstre ' + sentences[0]
                parts.extend(sentences)
                if nodebt:
                    if len(nodebt) == 1:
                        parts.append(nodebt[0] + ' borcunuz bulunmamaktadır.')
                    else:
                        parts.append(', '.join(nodebt[:-1]) + ' ve ' + nodebt[-1] + ' borcunuz bulunmamaktadır.')
                tl = d.get('debtTL') if isinstance(d.get('debtTL'), dict) else dict()
                if lp and lp < today and str(d.get('automaticPaymentFlag')) == 'Y' and num(tl.get('remainAutomaticPaymentAmount')) > 0:
                    parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + amount(tl.get('remainAutomaticPaymentAmount'), 'TL', True) + '.')
                if lp and lp < today:
                    parts.append('Son ödeme tarihiniz ' + sdate(lpd) + ' tarihinde geçmiştir.')
                    if num(tl.get('totalDebt')) > 0:
                        parts.append('Toplam borcunuz ' + amount(tl.get('totalDebt'), 'TL', True) + '.')
                elif lp and lp == today:
                    parts.append('Borçlarınız için son ödeme tarihiniz bugündür.')
                elif lpd:
                    parts.append('Borçlarınız için son ödeme tarihiniz ' + date_cop(lpd) + '.')
        txt = ' '.join(parts)
        vars['reading_text'] = txt
        vars['bal_state'] = 'ok'
        set_out(result, 'Okuma metni hazır. Kendin bir şey söyleme; metin sabit olarak okunacak.', txt)
except Exception:
    vars['bal_state'] = 'error'

